import wiki from './place-wiki.json';

// What the place panel shows about a place, by its name on the map. Summaries and facts come from A Wiki of Ice and Fire
// (src/place-wiki.json, generated by tools/wiki/place-info.mjs); entries written here go on top of them.
export interface PlaceInfo {
  /** Photo or art at the top of the panel (URL or path under public/). */
  image?: string;
  /** The gallery: file names of the article's pictures, as in awoiaf's thumb.php?f=. */
  images?: string[];
  summary?: string;
  /** Rows under the summary, [label, value]: ['Ruler', 'House Stark'], ['Founded', 'Age of Heroes']. */
  facts?: [string, string][];
  /** Title of the place's article on A Wiki of Ice and Fire, when the text is from there. */
  wiki?: string;
}

export const PLACE_INFO: Record<string, PlaceInfo> = { ...(wiki as unknown as Record<string, PlaceInfo>) };
